INSERT INTO products (sku, name, category, description, main_flowers, color_tone, size, unit, price, lead_time_hours, freshness_days, is_seasonal, season_note, is_active) VALUES
  ('BH01', 'Bó Nắng Sớm', 'bo_hoa', 'Bó hoa tươi sáng cho sinh nhật, tốt nghiệp, chúc mừng đồng nghiệp.', 'Hướng dương, cúc mẫu đơn trắng, lá bạc', 'Vàng – trắng', 'Cao 45cm', 'bó', 350000, 3, 3, 0, NULL, 1),
  ('BH02', 'Bó Thương Thương', 'bo_hoa', 'Bó hồng đỏ kinh điển cho người thương, kỷ niệm, 20/10.', '10 hồng đỏ Đà Lạt, baby trắng', 'Đỏ – trắng', 'Cao 50cm', 'bó', 420000, 3, 3, 0, NULL, 1),
  ('BH03', 'Bó Mộc Miên', 'bo_hoa', 'Bó hoa đặc trưng của tiệm, hồng Ecuador bông to, giữ form lâu.', '20 hồng đỏ Ecuador, lá bạc, cỏ đuôi thỏ', 'Đỏ thẫm', 'Cao 60cm', 'bó', 1250000, 6, 3, 0, NULL, 1),
  ('BH04', 'Bó Hồng Phấn', 'bo_hoa', 'Tông hồng phấn nhẹ nhàng, hợp tặng mẹ, cô giáo, bạn gái.', '15 hồng kem dâu, cẩm chướng hồng, baby', 'Hồng pastel', 'Cao 50cm', 'bó', 550000, 3, 3, 0, NULL, 1),
  ('BH05', 'Bó Cát Tường', 'bo_hoa', 'Cát tường mang ý nghĩa may mắn, hợp tặng khai trương nhỏ, thi cử.', 'Cát tường tím, thạch thảo, lá phi lao', 'Tím – trắng', 'Cao 45cm', 'bó', 380000, 3, 3, 0, NULL, 1),
  ('BH06', 'Bó Tulip Hà Lan', 'bo_hoa', 'Tulip nhập khẩu theo mùa (tháng 10 – tháng 4), màu tùy lô hàng.', '10 tulip nhập Hà Lan, lá bạc', 'Theo màu tulip có sẵn', 'Cao 45cm', 'bó', 890000, 6, 3, 1, 'Có từ tháng 10 đến tháng 4; màu theo lô nhập trong tuần.', 1),
  ('BH07', 'Bó Baby Trắng', 'bo_hoa', 'Bó baby trắng tinh khôi, chụp ảnh đẹp.', 'Baby trắng Đà Lạt, giấy kraft', 'Trắng', 'Đường kính 35cm', 'bó', 320000, 3, 3, 0, NULL, 1),
  ('BH08', 'Bó Tốt Nghiệp Rạng Rỡ', 'bo_hoa', 'Bó nhỏ gọn cho lễ tốt nghiệp, khai giảng.', '3 hướng dương, đồng tiền cam, cúc tana', 'Vàng – cam', 'Cao 40cm', 'bó', 290000, 3, 3, 0, NULL, 1),
  ('BH09', 'Bó 99 Hồng Trọn Đời', 'bo_hoa', 'Bó hoa cầu hôn, kỷ niệm lớn. Đặt trước tối thiểu 24 giờ.', '99 hồng đỏ Đà Lạt, baby, ruy băng satin', 'Đỏ', 'Đường kính 70cm', 'bó', 2990000, 24, 3, 0, NULL, 1),
  ('BH10', 'Bó Mẫu Đơn', 'bo_hoa', 'Mẫu đơn nhập khẩu, chỉ nhận đặt trước theo mùa.', '7 mẫu đơn nhập, hồng kem, lá bạc', 'Hồng phấn', 'Cao 50cm', 'bó', 1590000, 72, 3, 1, 'Mùa chính tháng 4 – tháng 6; ngoài mùa đặt trước tối thiểu 3 ngày và tùy nguồn nhập.', 1),
  ('BH11', 'Bó Cẩm Tú Cầu Xanh', 'bo_hoa', 'Cẩm tú cầu bông to, rất cần nước — cam kết tươi 2 ngày.', '3 cẩm tú cầu xanh Đà Lạt, lá bạc', 'Xanh dương', 'Đường kính 40cm', 'bó', 480000, 3, 2, 0, NULL, 1),
  ('GH01', 'Hộp Hoa Ngọt Ngào', 'gio_hop_hoa', 'Hộp hoa xinh xắn, không cần cắm bình.', 'Hồng pastel, cẩm chướng, baby trong hộp tròn', 'Hồng – kem', 'Hộp tròn 25cm', 'hộp', 520000, 3, 3, 0, NULL, 1),
  ('GH02', 'Giỏ Hoa Tri Ân', 'gio_hop_hoa', 'Giỏ hoa tặng thầy cô, đối tác, cha mẹ.', 'Đồng tiền, cúc mẫu đơn, hồng, lá chanh', 'Nhiều màu', 'Giỏ mây 40cm', 'giỏ', 650000, 4, 3, 0, NULL, 1),
  ('GH03', 'Hộp Hoa Socola', 'gio_hop_hoa', 'Hộp hoa kèm socola cho dịp kỷ niệm, Valentine, 20/10.', '9 hồng đỏ + 8 viên socola', 'Đỏ', 'Hộp vuông 25cm', 'hộp', 690000, 3, 3, 0, NULL, 1),
  ('GH04', 'Giỏ Trái Cây Miệt Vườn & Hoa', 'gio_hop_hoa', 'Trái cây miệt vườn theo mùa kèm hoa, hợp thăm hỏi, biếu tặng.', 'Trái cây vườn Phong Điền theo mùa + hoa cúc, hồng', 'Nhiều màu', 'Giỏ 45cm', 'giỏ', 990000, 6, 3, 0, NULL, 1),
  ('BN01', 'Bình Hoa Bàn Làm Việc', 'binh_hoa', 'Bình nhỏ để bàn làm việc, quầy lễ tân.', 'Hoa mix theo mùa trong bình thủy tinh nhỏ', 'Theo mùa', 'Cao 25cm', 'bình', 300000, 3, 3, 0, NULL, 1),
  ('BN02', 'Bình Hoa Sảnh Lễ Tân', 'binh_hoa', 'Bình lớn cho sảnh khách sạn, văn phòng. Đặt trước 24 giờ.', 'Lily, hồng, lá trầu bà, cành thân gỗ', 'Sang trọng theo yêu cầu', 'Cao 80cm', 'bình', 1200000, 24, 3, 0, NULL, 1),
  ('BN03', 'Bình Hoa Cúng', 'binh_hoa', 'Bình hoa cúng ngày rằm, mùng một, giỗ chạp.', 'Cúc vàng, lay ơn, huệ trắng (tùy mùa)', 'Vàng – đỏ – trắng', 'Cao 60cm', 'bình', 220000, 3, 3, 0, NULL, 1),
  ('KT01', 'Kệ Khai Trương Phát Lộc (1 tầng)', 'ke_khai_truong', 'Kệ 1 tầng kèm băng rôn chúc mừng in miễn phí.', 'Đồng tiền, hồng, lay ơn, lá cọ', 'Đỏ – vàng', 'Cao 1,6m', 'kệ', 800000, 6, 1, 0, NULL, 1),
  ('KT02', 'Kệ Khai Trương Hồng Phát (2 tầng)', 'ke_khai_truong', 'Kệ 2 tầng, phù hợp khai trương cửa hàng, văn phòng.', 'Hồng, lan vũ nữ, đồng tiền, lay ơn', 'Đỏ – vàng', 'Cao 1,8m', 'kệ', 1500000, 6, 1, 0, NULL, 1),
  ('KT03', 'Kệ Khai Trương Đại Cát (3 tầng)', 'ke_khai_truong', 'Kệ 3 tầng sang trọng cho khai trương công ty, nhà hàng. Đặt trước 12 giờ.', 'Hồng Ecuador, lan hồ điệp cắt cành, cát tường, lay ơn', 'Đỏ – vàng – trắng', 'Cao 2,2m', 'kệ', 2600000, 12, 1, 0, NULL, 1),
  ('CB01', 'Kệ Chia Buồn Tiễn Biệt', 'hoa_chia_buon', 'Kệ chia buồn tông trắng, kèm băng đen in lời tiễn biệt.', 'Cúc trắng, lan trắng, lay ơn trắng', 'Trắng – xanh', 'Cao 1,6m', 'kệ', 1200000, 3, 1, 0, NULL, 1),
  ('CB02', 'Vòng Hoa Vĩnh Hằng', 'hoa_chia_buon', 'Vòng hoa viếng truyền thống, trang nghiêm.', 'Cúc trắng, hồng trắng, lan tím', 'Trắng – tím', 'Đường kính 1m', 'vòng', 1800000, 3, 1, 0, NULL, 1),
  ('CB03', 'Kệ Chia Buồn Thanh Thản (2 tầng)', 'hoa_chia_buon', 'Kệ 2 tầng thay lời tiễn biệt của tập thể, cơ quan.', 'Lan hồ điệp trắng, cúc mẫu đơn, lily trắng', 'Trắng', 'Cao 1,9m', 'kệ', 2500000, 4, 1, 0, NULL, 1),
  ('HC01', 'Hoa Cầm Tay Cô Dâu Hồng Trắng', 'hoa_cuoi', 'Hoa cầm tay cổ điển, đặt trước tối thiểu 48 giờ.', 'Hồng trắng, baby, lá bạc', 'Trắng', 'Đường kính 25cm', 'bó', 650000, 48, 1, 0, NULL, 1),
  ('HC02', 'Hoa Cầm Tay Cô Dâu Cẩm Tú Cầu', 'hoa_cuoi', 'Hoa cầm tay tông xanh nhẹ, chụp ngoại cảnh đẹp.', 'Cẩm tú cầu, hồng kem, lá bạc', 'Xanh – trắng', 'Đường kính 28cm', 'bó', 750000, 48, 1, 0, NULL, 1),
  ('HC03', 'Hoa Cài Áo Chú Rể', 'hoa_cuoi', 'Đặt cùng hoa cầm tay để đồng bộ.', 'Hồng mini, baby', 'Theo hoa cô dâu', '8cm', 'cái', 60000, 48, 1, 0, NULL, 1),
  ('HC04', 'Hoa Cổ Tay Phù Dâu', 'hoa_cuoi', 'Hoa đeo tay cho phù dâu.', 'Hồng mini, baby, ruy băng', 'Theo hoa cô dâu', '10cm', 'cái', 90000, 48, 1, 0, NULL, 1),
  ('LC01', 'Lan Hồ Điệp 3 Cành Trắng', 'lan_chau', 'Chậu lan sang trọng, hoa giữ 3–6 tuần nếu chăm đúng.', '3 cành lan hồ điệp trắng, chậu sứ', 'Trắng', 'Cao 70cm', 'chậu', 1350000, 4, 21, 0, NULL, 1),
  ('LC02', 'Lan Hồ Điệp 5 Cành Vàng', 'lan_chau', 'Hợp tặng khai trương, tân gia, đối tác.', '5 cành lan hồ điệp vàng, chậu gốm men', 'Vàng', 'Cao 80cm', 'chậu', 2250000, 6, 21, 0, NULL, 1),
  ('LC03', 'Lan Hồ Điệp Mini 1 Cành', 'lan_chau', 'Chậu lan nhỏ để bàn.', '1 cành lan hồ điệp mini, chậu sứ nhỏ', 'Tím / trắng / hồng', 'Cao 35cm', 'chậu', 390000, 3, 21, 0, NULL, 1),
  ('HL01', 'Hồng đỏ Đà Lạt', 'hoa_le', 'Bán lẻ theo cành tại cửa hàng hoặc giao kèm đơn.', 'Hồng đỏ', 'Đỏ', 'Cành 50–60cm', 'cành', 18000, 0, 2, 0, NULL, 1),
